CREATE TABLE pushMessages (
    id serial NOT NULL CONSTRAINT push_message_pr_key PRIMARY KEY,
    messageType VARCHAR(50) NOT NULL,
    deviceId INT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    payload TEXT
);

ALTER TABLE pendingPushes ADD COLUMN device_sequence_num BIGINT, ADD COLUMN delivered_ack_at BIGINT, ADD COLUMN executed_ack_at BIGINT, ADD COLUMN failed_at BIGINT, ADD COLUMN failure_code VARCHAR(64), ADD COLUMN failure_message TEXT, ADD COLUMN retry_count INT NOT NULL DEFAULT 0, ADD COLUMN max_retries INT NOT NULL DEFAULT 3, ADD COLUMN next_attempt_at BIGINT, ADD COLUMN expires_at BIGINT, ADD COLUMN correlation_id UUID, ADD COLUMN created_by_user_id INT REFERENCES users(id), ADD COLUMN created_by_source VARCHAR(32);
CREATE INDEX idx_pending_state_device ON pendingPushes (status, messageId);
CREATE INDEX idx_pending_next_attempt ON pendingPushes (next_attempt_at) WHERE next_attempt_at IS NOT NULL;
CREATE INDEX idx_pending_expires ON pendingPushes (expires_at) WHERE expires_at IS NOT NULL;

CREATE OR REPLACE FUNCTION fn_pending_pushes_set_sequence()
RETURNS TRIGGER AS $$
DECLARE
    v_device_id INT;
    v_next_seq BIGINT;
BEGIN
    SELECT deviceId INTO v_device_id FROM pushMessages WHERE id = NEW.messageId;

    SELECT COALESCE(MAX(p.device_sequence_num), 0) + 1
    INTO v_next_seq
    FROM pendingPushes p
    INNER JOIN pushMessages m ON m.id = p.messageId
    WHERE m.deviceId = v_device_id;

    NEW.device_sequence_num := v_next_seq;
    NEW.expires_at := COALESCE(NEW.expires_at, NEW.createTime + (7 * 24 * 3600 * 1000));
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_pending_pushes_sequence
BEFORE INSERT ON pendingPushes
FOR EACH ROW EXECUTE FUNCTION fn_pending_pushes_set_sequence();

CREATE TABLE mdm_command_audit (
    id BIGSERIAL PRIMARY KEY,
    message_id INT NOT NULL,
    event_type VARCHAR(32) NOT NULL,
    from_state VARCHAR(24),
    to_state VARCHAR(24),
    event_at BIGINT NOT NULL DEFAULT (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT,
    actor VARCHAR(128),
    details JSONB,
    ip_address INET
);

CREATE INDEX idx_audit_message ON mdm_command_audit (message_id, event_at);
CREATE INDEX idx_audit_event_at ON mdm_command_audit (event_at);
CREATE INDEX idx_audit_event_type ON mdm_command_audit (event_type);

UPDATE pendingPushes
SET expires_at = createTime + (7 * 24 * 3600 * 1000)
WHERE expires_at IS NULL;
